void gentdrow(POLY_QBIG *t0, POLY_QBIG *t1, POLY_QBIG *t2, POLY_QBIG *td,
              const POLY_QBIG g_hat[][N_HAT]) {
  POLY_QBIG e0[M_HAT];
  POLY_QBIG e1[V_1];
  POLY_QBIG e2[V_2];

  uint64_t i, j;

  /* s<--R_{\hat{q}}^{\hat{n}-1} */
  sample_s(td);

  /* e_0<--{-B_e...B_e}^{\hat{m}*d} */
  sample_be_mhatd(e0);
  /* e_1<--{-B_e...B_e}^{v_1*d} */
  sample_be_v1d(e1);
  /* e_2<--{-B_e...B_e}^{v_2*d} */
  sample_be_v2d(e2);

  /* ntt */
  for (i = 0; i < M_HAT; i++) {
    ntt_qbig(e0 + i);
    memcpy(t0 + i, e0 + i, sizeof(POLY_QBIG));
  }

  for (i = 0; i < V_1; i++) {
    ntt_qbig(e1 + i);
    memcpy(t1 + i, e1 + i, sizeof(POLY_QBIG));
  }

  for (i = 1; i < N_SPENT; i++) {
    for (j = 0; j < D; j++) {
      t1[i].poly1[j] += tg_0[i - 1].poly1[j];
      t1[i].poly2[j] += tg_0[i - 1].poly2[j];
    }
  }

  /* extension para N_SPENT > 100: la tabla tg_0 solo trae 99 entradas
   * (las demas quedan en cero); las posiciones >= 100 se generan con la
   * formula del gadget (Ap. E.1): NTT(t_bar * P_i(X)), P_i = bits de i.
   * Verificado: reproduce la tabla exacta en las posiciones 1..99. */
  for (i = 100; i < N_SPENT; i++) {
    POLY_QBIG ge;
    for (j = 0; j < D; j++) {
      uint64_t bit = (i >> j) & 1ULL;
      ge.poly1[j] = bit ? (uint64_t)T_BAR_QBIG1 : 0;
      ge.poly2[j] = bit ? (uint64_t)T_BAR_QBIG2 : 0;
    }
    ntt_qbig(&ge);
    for (j = 0; j < D; j++) {
      t1[i].poly1[j] += ge.poly1[j];
      t1[i].poly2[j] += ge.poly2[j];
    }
  }

  for (i = V_1 - S * R; i < V_1; i++) {
    for (j = 0; j < D; j++) {
      t1[i].poly1[j] += tg_1[i - (V_1 - S * R)].poly1[j];
      t1[i].poly2[j] += tg_1[i - (V_1 - S * R)].poly2[j];
    }
  }

  for (i = 0; i < V_2; i++) {
    ntt_qbig(e2 + i);
    memcpy(t2 + i, e2 + i, sizeof(POLY_QBIG));
  }

  /* t_0=A^{T}*s+e_0 */
  for (i = 0; i < M_HAT; i++) {
    for (j = 0; j < N_HAT - 1; j++) {
      mult_plus_rqbig(t0 + i, g_hat[i] + j, td + j);
    }

    for (j = 0; j < D; j++) {
      t0[i].poly1[j] = red_short_qbig1(t0[i].poly1[j]);
      t0[i].poly2[j] = red_short_qbig2(t0[i].poly2[j]);
    }
  }

  /* t_1=B^{T}*s+e_1+\bar{t}*g */
  for (i = 0; i < V_1; i++) {
    for (j = 0; j < N_HAT - 1; j++) {
      mult_plus_rqbig(t1 + i, g_hat[M_HAT + i] + j, td + j);
    }

    for (j = 0; j < D; j++) {
      t1[i].poly1[j] = red_short_qbig1(t1[i].poly1[j]);
      t1[i].poly2[j] = red_short_qbig2(t1[i].poly2[j]);
    }
  }

  /* t_2=C^{T}*s+e_2 */
  for (i = 0; i < V_2; i++) {
    for (j = 0; j < N_HAT - 1; j++) {
      mult_plus_rqbig(t2 + i, g_hat[M_HAT + V_1 + i] + j, td + j);
    }

    for (j = 0; j < D; j++) {
      t2[i].poly1[j] = red_short_qbig1(t2[i].poly1[j]);
      t2[i].poly2[j] = red_short_qbig2(t2[i].poly2[j]);
    }
  }

  /* td=(-s,1) */
  for (i = 0; i < N_HAT - 1; i++) {
    for (j = 0; j < D; j++) {
      td[i].poly1[j] = QBIG1 - td[i].poly1[j];
      td[i].poly2[j] = QBIG2 - td[i].poly2[j];
    }
  }
}
